package com.brightloop.notification;
import jakarta.persistence.*;import java.time.Instant;
@Entity @Table(name="notifications") public class Notification{
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id;@Column(name="recipient_email",nullable=false,length=190) String recipientEmail;@Column(name="notification_type",nullable=false,length=40) String notificationType;@Column(nullable=false,length=190) String subject;@Column(nullable=false,columnDefinition="TEXT") String content;@Column(name="event_key",nullable=false,unique=true,length=190) String eventKey;@Column(name="delivery_status",nullable=false,length=20) String deliveryStatus;@Column(name="error_message",length=500) String errorMessage;@Column(name="created_at",nullable=false,updatable=false) Instant createdAt=Instant.now();protected Notification(){}public Notification(String email,String type,String subject,String body,String key,String status){recipientEmail=email;notificationType=type;this.subject=subject;content=body;eventKey=key;deliveryStatus=status;}public void status(String status,String error){deliveryStatus=status;errorMessage=error;}public Long getId(){return id;}public String getRecipientEmail(){return recipientEmail;}public String getNotificationType(){return notificationType;}public String getSubject(){return subject;}public String getDeliveryStatus(){return deliveryStatus;}public Instant getCreatedAt(){return createdAt;}}
